// Side panel that shows what a finished certificate looks like: the template's
// reference image (uploaded or generated by the Super Admin), or — when it has
// none — the template rendered with sample text in the browser.

import React, { useEffect, useState } from 'react';
import { ChevronDown, ChevronUp, Eye, Maximize2 } from 'lucide-react';
import { fileUrl } from '../../lib/api';
import { Card, Modal, Skeleton, cx } from '../shared/ui';
import type { ClientTemplate } from '../../../shared/types';
import { renderSamplePng } from '../../engine/sampleRender';

const samples = new Map<string, Promise<string>>();

/** Object URL of a sample render, cached per template version for this visit. */
function sampleUrl(t: ClientTemplate): Promise<string> {
  let p = samples.get(t.versionId);
  if (!p) {
    p = renderSamplePng(t.layout, 1200).then((b) => URL.createObjectURL(b));
    samples.set(t.versionId, p);
    p.catch(() => samples.delete(t.versionId));
  }
  return p;
}

export function useReferenceImage(t: ClientTemplate | null) {
  const [url, setUrl] = useState<string | null>(null);
  const [kind, setKind] = useState<'reference' | 'sample' | null>(null);
  const [error, setError] = useState(false);
  useEffect(() => {
    setError(false);
    if (!t) {
      setUrl(null);
      setKind(null);
      return;
    }
    if (t.referenceImageFileId) {
      setUrl(fileUrl(t.referenceImageFileId)!);
      setKind('reference');
      return;
    }
    let live = true;
    setUrl(null);
    setKind('sample');
    sampleUrl(t)
      .then((u) => live && setUrl(u))
      .catch(() => live && setError(true));
    return () => {
      live = false;
    };
  }, [t?.versionId, t?.referenceImageFileId]); // eslint-disable-line react-hooks/exhaustive-deps
  return { url, kind, error };
}

/**
 * Template thumbnail for Admin and User listings: always the reference
 * (filled-in sample) certificate, never the blank design.
 */
export function ReferenceThumb({ template, className }: { template: ClientTemplate; className?: string }) {
  const { url, error } = useReferenceImage(template);
  return (
    <div className={cx('paper relative aspect-[1.414] w-full overflow-hidden', className)}>
      {url ? (
        <img src={url} alt={`Example of ${template.title}`} className="h-full w-full object-contain" loading="lazy" />
      ) : error ? (
        <div className="flex h-full items-center justify-center text-xs text-slate-400">Example not available</div>
      ) : (
        <Skeleton className="h-full w-full rounded-none" />
      )}
    </div>
  );
}

export function ReferencePanel({ template, className, title = 'What the certificate looks like' }: { template: ClientTemplate | null; className?: string; title?: string }) {
  const { url, kind, error } = useReferenceImage(template);
  const [open, setOpen] = useState(true);
  const [zoom, setZoom] = useState(false);

  return (
    <Card className={cx('overflow-hidden', className)}>
      <button type="button" onClick={() => setOpen((o) => !o)} className="flex w-full items-center justify-between gap-2 border-b border-slate-100 px-4 py-3 text-left" aria-expanded={open}>
        <span className="flex items-center gap-2 text-sm font-semibold text-slate-900">
          <Eye className="h-4 w-4 text-navy" /> {title}
        </span>
        {open ? <ChevronUp className="h-4 w-4 text-slate-400" /> : <ChevronDown className="h-4 w-4 text-slate-400" />}
      </button>
      {open && (
        <div className="p-3">
          {!template ? (
            <p className="px-2 py-10 text-center text-sm text-slate-500">Choose a template to see an example certificate.</p>
          ) : error ? (
            <p className="px-2 py-10 text-center text-sm text-slate-500">The example could not be shown.</p>
          ) : !url ? (
            <Skeleton className="aspect-[1.414] w-full" />
          ) : (
            <button type="button" onClick={() => setZoom(true)} className="group paper relative block w-full overflow-hidden rounded-lg border border-slate-200" aria-label="Enlarge example certificate">
              <img src={url} alt={`Example of ${template.title}`} className="w-full object-contain" />
              <span className="absolute right-2 top-2 rounded-md bg-white/90 p-1 text-slate-600 opacity-0 shadow transition group-hover:opacity-100">
                <Maximize2 className="h-4 w-4" />
              </span>
            </button>
          )}
          {template && (
            <p className="mt-2 px-1 text-xs text-slate-500">
              {kind === 'reference' ? 'Reference certificate provided for this template.' : 'Example with sample names, photo and signature — your own wording and data will appear instead.'}
            </p>
          )}
        </div>
      )}
      {zoom && url && template && (
        <Modal open onClose={() => setZoom(false)} title={template.title} size="xl">
          <div className="paper rounded-lg">
            <img src={url} alt={`Example of ${template.title}`} className="w-full object-contain" />
          </div>
        </Modal>
      )}
    </Card>
  );
}
